// so the parse tolerates that prefix — without it, a fetched log reads as having
// printed nothing at all.
const LINE_RE = new RegExp(
  String.raw`^(?:\S+\s+)?${TASK_RUN_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
);

